import React, { useState } from "react";
import styled from "styled-components";
import FastaTable from "./Fasta";
import VirulenceTable from "./Virulence";
import AmrTable from "./Amr";
import VirulenceListResult from "../components/VirulenceTableResult";
import { useTranslation } from "react-i18next";

const Container = styled.div`
  width: 100%;
  padding: 20px;
  display: flex;
  justify-content: center;
  align-items: center;
`;

const Wrapper = styled.div`
  width: 80%;
  max-width: 1200px;
  display: flex;
  flex-direction: column;
  align-items: center;
`;

const Title = styled.h1`
  font-size: 36px;
  font-weight: bold;
  color: #333;
  margin-bottom: 20px;
  text-align: center;
`;

const ButtonGroup = styled.div`
  display: flex;
  justify-content: center;
  margin-bottom: 20px;
`;

const Button = styled.button`
  padding: 10px 20px;
  background-color: transparent;
  color: ${(props) => (props.selected ? "#007bff" : "#000")};
  border: 2px solid ${(props) => (props.selected ? "#007bff" : "#ccc")};
  border-radius: 5px;
  font-size: 25px;
  font-weight: ${(props) => (props.selected ? "bold" : "normal")};
  cursor: pointer;
  margin: 0 30px;
  &:last-child {
    margin-right: 0;
  }
`;

const ImageWrapper = styled.div`
  position: relative;
  width: 100%;
`;

const Image = styled.img`
  width: 100%;
  height: auto;
  display: block;
`;

const ClickArea = styled.div`
  position: absolute;
  cursor: pointer;
  background: ${(props) =>
    props.active ? "rgba(255, 33, 66, 0.15);" : "transparent"};
  border-radius: 5px;
  transition: background 0.3s;

  &:hover {
    background: rgba(255, 33, 66, 0.15);
  }
`;

const ResultComponent = ({ fastaInfo, virulenceInfo, amrInfo }) => {
  const [selectedTab, setSelectedTab] = useState("Fasta");

  const handleTabClick = (tab) => {
    setSelectedTab(tab);
  };
  const [label, setLabel] = useState("");
  const { t } = useTranslation();

  return (
    <Container>
      <Wrapper>
        <Title>{t("resultComponent.analysisResult")}</Title>
        <ButtonGroup>
          <Button selected={selectedTab === "Fasta"} onClick={() => handleTabClick("Fasta")}>
            {t("resultComponent.fasta")}
          </Button>
          <Button selected={selectedTab === "Virulence"} onClick={() => handleTabClick("Virulence")}>
            {t("resultComponent.virulence")}
          </Button>
          <Button selected={selectedTab === "AMR"} onClick={() => handleTabClick("AMR")}>
            {t("resultComponent.amr")}
          </Button>
        </ButtonGroup>

        {selectedTab === "Fasta" && <FastaTable sample={fastaInfo} />}
        {selectedTab === "Virulence" && <VirulenceTable data={virulenceInfo} />}
        {selectedTab === "AMR" && <AmrTable data={amrInfo} />}

        <ImageWrapper>
          <Image src="/Bacteria-Cell.jpg" alt="Bacteria" />
          <ClickArea style={{ top: "17%", left: "40%", width: "30%", height: "10%" }} onClick={() => setLabel(t("resultComponent.nucleoid"))} />
          <ClickArea style={{ top: "15%", left: "0%", width: "20%", height: "10%" }} onClick={() => setLabel(t("resultComponent.ribosomes"))} />
          <ClickArea style={{ top: "10%", left: "27%", width: "20%", height: "8%" }} onClick={() => setLabel(t("cytoplasm"))} />
          <ClickArea style={{ top: "40%", left: "82%", width: "20%", height: "12%" }} onClick={() => setLabel(t("plasmid"))} />
          <ClickArea style={{ top: "23%", left: "80%", width: "15%", height: "10%" }} onClick={() => setLabel(t("pili"))} />
          <ClickArea style={{ top: "62%", left: "70%", width: "25%", height: "15%" }} onClick={() => setLabel(t("inclusionBodies"))} />
          <ClickArea style={{ top: "80%", left: "57%", width: "25%", height: "12%" }} onClick={() => setLabel(t("flagellum"))} />
          <ClickArea style={{ top: "79%", left: "29%", width: "25%", height: "12%" }} onClick={() => setLabel(t("cytoplasmicMembrane"))} />
          <ClickArea style={{ top: "76%", left: "8%", width: "20%", height: "10%" }} onClick={() => setLabel(t("cellWall"))} />
          <ClickArea style={{ top: "66%", left: "3%", width: "20%", height: "10%" }} onClick={() => setLabel(t("capsule"))} />
        </ImageWrapper>

        {label && <VirulenceListResult label={label} data={virulenceInfo} />}
      </Wrapper>
    </Container>
  );
};

export default ResultComponent;
